  "home.tenancyAgreementPurchaseContract": "Bérleti szerződés, adásvételi szerződés, átadás-átvételi jegyzőkönyv, közüzemi költség-elszámolások, energetikai tanúsítvány … PDF-ként vagy fotóként. A „Dokumentumok” alatt a megfelelő kategóriában kerülnek iktatásra, és itt is megjelennek.",
  "home.tenancyPurchaseContractDeposit": "Bérleti vagy adásvételi szerződés, óvadék, hibák fotókkal, nyugták bútorokról és padlókról, felújítási terv, közüzemi költségek, mérőóra-állások előrejelzéssel, kert és növények, valamint egy karbantartási terv, amely időben kiosztja a feladatokat – a kiadott lakásokhoz, házakhoz és garázsokhoz is. Minden egy helyen, a dokumentumokhoz és a pénzügyekhez kapcsolva.",
