  "home.tipWhenMovingRecord": "Tipp: beköltözéskor rögzítsd a meglévő hibákat fotókkal a „Hibák” alatt „megvolt beköltözéskor” megjelöléssel – ez kiköltözéskor védi az óvadékodat.",
