  "loc.enterInternetConnectionsAddress": "Add meg az internetkapcsolatod címét szerverként (pl. a MyFRITZ!-címedet) – általában SMS-paranccsal, a nyomkövető kézikönyve szerint.",
  "loc.enterShopAddressesUnder": "Az üzletek címét a Listák → Bevásárlólista szerkesztése alatt adod meg – ha egy üzlet több helyen is létezik, több fiókot is. Ha valaki egy ideig ott tartózkodik, a tervezett bevásárlás kipipálódik.",
