  "loc.gpsTracker": "🛰️ GPS-nyomkövető",
  "loc.guide1": "Telepítsd a <b>„Traccar Client”</b> alkalmazást (App Store vagy Google Play, ingyenes).",
  "loc.guide2": "Az alkalmazásban az <b>Eszközazonosító</b> (Device identifier) alatt add meg:",
  "loc.guide3": "A <b>Szerver URL</b> alatt add meg:",
  "loc.guide4": "Pontosság: <b>Közepes</b>, távolság: <b>50 m</b>. Az alkalmazás ekkor csak mozgáskor küld – állva semmit. Ha további mezők is vannak (időköz, heartbeat), a heartbeat-et kapcsold ki vagy állítsd 0-ra.",
  "loc.guide5": "Engedélyezd a helyhozzáférést: <b>Mindig</b>, és a <b>Pontos helyzet</b> legyen bekapcsolva.",
  "loc.guide6": "Kapcsold be a <b>Szolgáltatás / Követés</b> kapcsolót, és <b>hagyd mindig bekapcsolva</b> – kész. Mostantól mindent a pinn.-ben vezérelsz: „Folyamatos küldés” be vagy ki, „Egyszeri küldés” és SOS. Amíg a „Folyamatos küldés” ki van kapcsolva, senki sem látja a helyzetedet, és a pinn. nem rögzít útvonalat.",
  "loc.guideIntro": "Más alkalmazás nélkül a „📍 Helyzet megosztása” közvetlenül a pinn.-ben működik – de csak amíg a pinn. nyitva van. Hogy a helyzet akkor is megérkezzen, ha a pinn. be van zárva, és a képernyő le van zárva, az ingyenes „Traccar Client” alkalmazás közvetlenül a pinn.-nek küldi (Traccar-szerver nem szükséges). iPhone-on és Androidon ugyanígy.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Ezt a portot a FRITZ!Box-ban át kell irányítani a NAS-ra, mert a nyomkövető a mobilhálózatról csatlakozik.",
  "loc.haveGoodTripFamily": "Jó utat! A család értesítést kapott.",
