  "loc.ifSomeoneArrivesLeaves": "Ha valaki megérkezik egy helyre vagy elmegy onnan, push-értesítés érkezik. Az „Otthon” az „Úton vagyok” állapotot is befejezi.",
  "loc.ifTrackerHasSos": "Ha a nyomkövetőn van SOS-gomb, a pinn. push-üzenettel riasztja az egész családot (egy percen belül), amint a Traccar észleli a nyomkövető riasztását.",
