  "smart.haTip1": "Roborock: hozd létre a „Robotporszívó” eszközt, válaszd ki fent a robotot (vacuum.…) – a pinn. betölti a szobákat a térképről. Műveletenként „Szobatakarítás” szobákkal és móddal (porszívózás, porszívózás és felmosás, felmosás). A „Feladat szobája” a háztartási takarítási feladat szobáját használja – a neveknek egyezniük kell a Roborock alkalmazásban láthatókkal.",
  "smart.haTip2": "A robot állapotként is szolgál: a következő művelet csak akkor indul, ha visszatért a dokkolóra.",
